def transform(grid):
    """Fill enclosed zero regions according to the size of the enclosing cavity."""
    h, w = len(grid), len(grid[0])
    exterior = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c))
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c))
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in exterior:
                exterior.add((nr, nc))
                q.append((nr, nc))

    out = [row[:] for row in grid]
    seen = set(exterior)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            comp = []
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            # Cavity scale is the area of its bounding rectangle, including any 2s inside it.
            area = (max(rr for rr, _ in comp) - min(rr for rr, _ in comp) + 1) * (max(cc for _, cc in comp) - min(cc for _, cc in comp) + 1)
            color = 8 if area <= 9 else 4 if area <= 25 else 3
            for rr, cc in comp:
                out[rr][cc] = color
    return out
